// Helper functions
func getResultClass(status string) string {
	switch status {
	case "banned", "blocked":
		return "blocked"
	case "whitelisted":
		return "whitelisted"
	case "clean", "allowed":
		return "allowed"
	default:
		return ""
	}
}

func getStatusEmoji(status string) string {
	switch status {
	case "banned", "blocked":
		return "🚫"
	case "whitelisted":
		return "✅"
	case "clean", "allowed":
		return "✔️"
	default:
		return "❓"
	}
}

func getVerdictClass(status string) string {
	switch status {
	case "banned", "blocked":
		return "text-danger"
	case "whitelisted":
		return "text-info"
	case "clean", "allowed":
		return "text-safe"
	default:
		return ""
	}
}

func getSetTypeBadge(setType string) string {
	switch setType {
	case "blacklist":
		return "danger"
	case "whitelist":
		return "safe"
	case "feed":
		return "warning"
	case "geoban":
		return "info"
	default:
		return "secondary"
	}
}

